CREATE OR REPLACE TEMPORARY FUNCTION f(a INT) RETURNS STRING
RETURN CONCAT('x', CAST(a AS STRING));

CREATE FUNCTION IF NOT EXISTS f(a INT, b INT) RETURNS INT RETURN a + b;

CREATE FUNCTION f(a INT, b INT) RETURN a + b;

CREATE FUNCTION f() RETURNS INT RETURN (SELECT MAX(a) FROM t);

CREATE FUNCTION f() RETURNS INT RETURN SELECT MAX(a) FROM t;

CREATE FUNCTION f(a INT DEFAULT 1 + 2, b STRING DEFAULT CONCAT('x', 'y') COMMENT 'c')
RETURNS INT
RETURN a;

CREATE FUNCTION f(a INT) RETURNS INT
LANGUAGE SQL
NOT DETERMINISTIC
COMMENT 'adds nothing'
CONTAINS SQL
RETURN a;

CREATE FUNCTION f(a INT) RETURNS TABLE (x INT COMMENT 'x', y STRING)
READS SQL DATA
RETURN SELECT a, 'b';

CREATE FUNCTION f(a INT) RETURNS TABLE RETURN SELECT a;
